import{_ as i,c as e,o,ae as n}from"./chunks/framework.BQlYxExx.js";const r="/images/erd.png",t="/images/architektura.png",p=JSON.parse('{"title":"Założenia funkcjonalne i technikalia","description":"","frontmatter":{},"headers":[],"relativePath":"zalozenia.md","filePath":"zalozenia.md"}'),l={name:"zalozenia.md"};function s(c,a,z,d,m,u){return o(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="załozenia-funkcjonalne-i-technikalia" tabindex="-1">Założenia funkcjonalne i technikalia <a class="header-anchor" href="#załozenia-funkcjonalne-i-technikalia" aria-label="Permalink to &quot;Założenia funkcjonalne i technikalia&quot;">​</a></h1><h2 id="_2-1-załozenia-funkcjonalne" tabindex="-1">2.1. Założenia funkcjonalne <a class="header-anchor" href="#_2-1-załozenia-funkcjonalne" aria-label="Permalink to &quot;2.1. Założenia funkcjonalne&quot;">​</a></h2><p>Projekt ŁapGo to aplikacja webowa, której głównym celem jest ułatwienie procesu adopcji zwierząt. Kluczowe założenia funkcjonalne projektu to:</p><ul><li><strong>Centralna baza zwierząt</strong>: Aplikacja ma na celu indeksowanie (zbieranie i katalogowanie) informacji o zwierzętach przebywających w schroniskach na terenie całej Polski.</li><li><strong>Wyszukiwanie i dopasowywanie</strong>: Użytkownicy mogą wyszukiwać zwierzęta do adopcji. System ma dopasowywać i wyświetlać zwierzęta na podstawie określonych preferencji użytkownika (np. gatunek, wielkość, wiek, lokalizacja).</li><li><strong>Pośrednictwo w kontakcie</strong>: Aplikacja pełni rolę pośrednika, dostarczając użytkownikom niezbędnych informacji kontaktowych do schroniska, w którym przebywa wybrane zwierzę.</li><li><strong>Ułatwienie adopcji</strong>: Celem nadrzędnym jest pomoc użytkownikom w znalezieniu i adopcji wymarzonego zwierzęcia, poprzez dostarczenie im wszystkich kluczowych informacji w jednym miejscu.</li></ul><h2 id="_2-2-technikalia" tabindex="-1">2.2. Technikalia <a class="header-anchor" href="#_2-2-technikalia" aria-label="Permalink to &quot;2.2. Technikalia&quot;">​</a></h2><h3 id="_2-2-1-architektura-i-srodowisko" tabindex="-1">2.2.1. Architektura i Środowisko <a class="header-anchor" href="#_2-2-1-architektura-i-srodowisko" aria-label="Permalink to &quot;2.2.1. Architektura i Środowisko&quot;">​</a></h3><ul><li><p><strong>Docker (docker-compose.yaml)</strong>:</p><ul><li><em>Opis</em>: Platforma do konteneryzacji aplikacji.</li><li><em>Uzasadnienie</em>: Pozwala na stworzenie spójnego, przenośnego i izolowanego środowiska deweloperskiego. Każdy programista może uruchomić projekt lokalnie, mając pewność, że wszystkie usługi (aplikacja, baza danych, Redis) działają w tej samej konfiguracji. Znacząco upraszcza to proces wdrożenia i eliminuje problemy typu &quot;u mnie działało&quot;.</li></ul></li><li><p><strong>Make (Makefile)</strong>:</p><ul><li><em>Opis</em>: Narzędzie do automatyzacji zadań.</li><li><em>Uzasadnienie</em>: Działa jako &quot;nakładka&quot; na skomplikowane komendy Dockera i Composera. Upraszcza codzienne zadania (np. make init, make shell), czyniąc je łatwiejszymi do zapamiętania i wykonania.</li></ul></li><li><p><strong>Traefik</strong>:</p><ul><li><em>Opis</em>: Nowoczesny reverse proxy i load balancer.</li><li><em>Uzasadnienie</em>: Zintegrowany ze środowiskiem &quot;Blumilk traefik&quot;, pozwala na łatwe zarządzanie ruchem sieciowym i udostępnianie wielu lokalnych projektów pod przyjaznymi adresami URL (np. lapgo.blumilk.localhost).</li></ul></li></ul><h3 id="_2-2-2-backend-warstwa-aplikacji" tabindex="-1">2.2.2. Backend (Warstwa Aplikacji) <a class="header-anchor" href="#_2-2-2-backend-warstwa-aplikacji" aria-label="Permalink to &quot;2.2.2. Backend (Warstwa Aplikacji)&quot;">​</a></h3><ul><li><p><strong>PHP</strong>:</p><ul><li><em>Opis</em>: Język skryptowy po stronie serwera.</li><li><em>Uzasadnienie</em>: Dojrzały i popularny wybór do tworzenia aplikacji webowych, stanowiący fundament dla frameworka Laravel.</li></ul></li><li><p><strong>Laravel</strong>:</p><ul><li><em>Opis</em>: Wiodący framework PHP oparty na wzorcu MVC.</li><li><em>Uzasadnienie</em>: Drastycznie przyspiesza proces tworzenia aplikacji. Oferuje gotowe rozwiązania dla typowych zadań, takich jak routing, zarządzanie bazą danych (ORM Eloquent), uwierzytelnianie czy systemy kolejek.</li></ul></li><li><p><strong>Composer</strong>:</p><ul><li><em>Opis</em>: Menedżer zależności dla PHP.</li><li><em>Uzasadnienie</em>: Niezbędne narzędzie w nowoczesnym programowaniu w PHP. Pozwala na łatwe zarządzanie bibliotekami firm trzecich oraz automatyczne ładowanie klas.</li></ul></li><li><p><strong>PostgreSQL</strong>:</p><ul><li><em>Opis</em>: Zaawansowana, obiektowo-relacyjna baza danych SQL typu open-source.</li><li><em>Uzasadnienie</em>: Niezbędna do przechowywania danych o zwierzętach, schroniskach i preferencjach. Wybrany ze względu na swoją niezawodność, bogaty zestaw funkcji (np. lepsze wsparcie dla typów złożonych, JSONB) i ścisłe przestrzeganie standardów SQL.</li></ul></li><li><p><strong>Redis</strong>:</p><ul><li><em>Opis</em>: Magazyn danych typu klucz-wartość, działający w pamięci.</li><li><em>Uzasadnienie</em>: Używany do buforowania (cache) często odpytywanych danych, zarządzania sesjami lub kolejkami (queues). Znacząco poprawia to wydajność aplikacji poprzez odciążenie głównej bazy danych.</li></ul></li></ul><h3 id="_2-2-3-frontend-warstwa-prezentacji" tabindex="-1">2.2.3. Frontend (Warstwa Prezentacji) <a class="header-anchor" href="#_2-2-3-frontend-warstwa-prezentacji" aria-label="Permalink to &quot;2.2.3. Frontend (Warstwa Prezentacji)&quot;">​</a></h3><ul><li><p><strong>Vue.js</strong>:</p><ul><li><em>Opis</em>: Progresywny framework JavaScript do budowania interfejsów użytkownika.</li><li><em>Uzasadnienie</em>: Znane z niskiego progu wejścia i elastyczności. Umożliwia tworzenie reaktywnych i dynamicznych komponentów interfejsu (np. filtrowanie listy zwierząt &quot;na żywo&quot;), co znacząco poprawia doświadczenie użytkownika (UX).</li></ul></li><li><p><strong>Vite (vite.config.js)</strong>:</p><ul><li><em>Opis</em>: Narzędzie do budowania (build tool) i serwer deweloperski frontendu.</li><li><em>Uzasadnienie</em>: Wybór podyktowany wydajnością. Vite oferuje błyskawiczne przeładowywanie modułów (HMR - Hot Module Replacement) i szybki start serwera deweloperskiego.</li></ul></li><li><p><strong>Tailwind CSS</strong>:</p><ul><li><em>Opis</em>: Framework CSS typu &quot;utility-first&quot;.</li><li><em>Uzasadnienie</em>: Dostarcza zestaw klas użytkowych, co daje pełną kontrolę nad wyglądem i ułatwia budowanie niestandardowych, responsywnych interfejsów bez pisania własnego CSS od zera.</li></ul></li><li><p><strong>TypeScript</strong>:</p><ul><li><em>Opis</em>: Nadzbiór JavaScriptu dodający statyczne typowanie.</li><li><em>Uzasadnienie</em>: Pomaga wyłapywać błędy na wczesnym etapie pisania kodu i poprawia czytelność oraz utrzymanie kodu frontendu w miarę rozrastania się projektu.</li></ul></li></ul><h3 id="_2-2-4-jakosc-kodu-i-testowanie-ci-cd" tabindex="-1">2.2.4. Jakość Kodu i Testowanie (CI/CD) <a class="header-anchor" href="#_2-2-4-jakosc-kodu-i-testowanie-ci-cd" aria-label="Permalink to &quot;2.2.4. Jakość Kodu i Testowanie (CI/CD)&quot;">​</a></h3><ul><li><p><strong>PHPUnit</strong>:</p><ul><li><em>Opis</em>: Standardowy framework do testów jednostkowych i funkcjonalnych w PHP.</li><li><em>Uzasadnienie</em>: Kluczowe narzędzie do zapewnienia jakości kodu backendu. Pozwala na automatyczne weryfikowanie, czy poszczególne funkcje aplikacji działają zgodnie z oczekiwaniami.</li></ul></li><li><p><strong>PHP CS Fixer</strong>:</p><ul><li><em>Opis</em>: Narzędzie do automatycznego formatowania i poprawiania stylu kodu PHP zgodnie ze standardami (np. PSR-12).</li><li><em>Uzasadnienie</em>: Ułatwia utrzymanie spójnego stylu kodu, poprawia czytelność i zgodność z wybranymi standardami kodowania.</li></ul></li><li><p><strong>ESLint</strong>:</p><ul><li><em>Opis</em>: Linter dla kodu JavaScript/TypeScript.</li><li><em>Uzasadnienie</em>: Zapewnia spójność stylu kodowania w projekcie frontendowym i wyłapuje potencjalne problemy w kodzie.</li></ul></li><li><p><strong>GitHub Actions</strong>:</p><ul><li><em>Opis</em>: Platforma CI/CD zintegrowana z GitHubem.</li><li><em>Uzasadnienie</em>: Służy do automatyzacji procesów. Po każdym &quot;pushu&quot; do repozytorium automatycznie uruchamiane są testy (PHPUnit), analiza kodu (PHPStan) i lintowanie (ESLint).</li></ul></li><li><p><strong>Mailpit</strong>:</p><ul><li><em>Opis</em>: Lokalny serwer SMTP do przechwytywania wysyłanych maili.</li><li><em>Uzasadnienie</em>: Niezbędne narzędzie deweloperskie. Pozwala na łatwe testowanie funkcjonalności związanych z pocztą e-mail bez wysyłania prawdziwych wiadomości.</li></ul></li></ul><h3 id="_2-2-5-zarzadzanie-projektem-i-komunikacja" tabindex="-1">2.2.5. Zarządzanie projektem i komunikacja <a class="header-anchor" href="#_2-2-5-zarzadzanie-projektem-i-komunikacja" aria-label="Permalink to &quot;2.2.5. Zarządzanie projektem i komunikacja&quot;">​</a></h3><ul><li><p><strong>Git</strong>:</p><ul><li><em>Opis</em>: Rozproszony system kontroli wersji.</li><li><em>Uzasadnienie</em>: Niezbędny do śledzenia zmian w kodzie, pracy zespołowej nad tą samą bazą kodu, tworzenia gałęzi (branching) dla nowych funkcji oraz łatwego przywracania poprzednich wersji.</li></ul></li><li><p><strong>GitHub</strong>:</p><ul><li><em>Opis</em>: Platforma hostingowa dla repozytoriów Git, oferująca zarządzanie projektem i CI/CD.</li><li><em>Uzasadnienie</em>: Centralne miejsce do przechowywania kodu. Używany do przeglądów kodu (Pull Requests), zarządzania zadaniami (Issues/Backlog) oraz automatyzacji procesów (GitHub Actions), co łączy cały cykl życia oprogramowania.</li></ul></li><li><p><strong>Slack</strong>:</p><ul><li><em>Opis</em>: Komunikator biznesowy.</li><li><em>Uzasadnienie</em>: Wykorzystywany do codziennej, bieżącej komunikacji w zespole, szybkiego rozwiązywania problemów i dyskusji, co eliminuje potrzebę długich wątków mailowych i formalnych spotkań.</li></ul></li></ul><h2 id="_2-3-model-danych-i-architektura" tabindex="-1">2.3. Model Danych i Architektura <a class="header-anchor" href="#_2-3-model-danych-i-architektura" aria-label="Permalink to &quot;2.3. Model Danych i Architektura&quot;">​</a></h2><p>Dokumentacja techniczna została wzbogacona o Diagram Związków Encji (ERD), który przedstawia relacje między kluczowymi modelami danych, oraz o wysokopoziomowy Diagram Architektury Systemu.</p><h3 id="diagram-zwiazkow-encji-erd" tabindex="-1">Diagram Związków Encji (ERD) <a class="header-anchor" href="#diagram-zwiazkow-encji-erd" aria-label="Permalink to &quot;Diagram Związków Encji (ERD)&quot;">​</a></h3><p>Poniższy diagram przedstawia relacyjny model danych dla aplikacji ŁapGo, bazujący na bazie danych PostgreSQL. Wyróżnia on encje główne, takie jak PETS (Zwierzęta), PET_SHELTERS (Schroniska), USERS (Użytkownicy), oraz relacje polimorficzne (np. MEDIA, PET_TAG) dla zapewnienia elastyczności.</p><p><img src="'+r+'" alt="Diagram Związków Encji (ERD)"><em>Rysunek 1: Diagram Związków Encji (ERD) aplikacji ŁapGo.</em></p><h3 id="diagram-architektury-systemu" tabindex="-1">Diagram Architektury Systemu <a class="header-anchor" href="#diagram-architektury-systemu" aria-label="Permalink to &quot;Diagram Architektury Systemu&quot;">​</a></h3><p>Poniższy diagram ilustruje wysokopoziomową architekturę systemu, pokazując, jak różne komponenty (Backend, Frontend, Infrastruktura) komunikują się ze sobą, ze szczególnym uwzględnieniem mechanizmu scrapera AI opartego na API Gemini.</p><p><img src="'+t+'" alt="Diagram Architektury Systemu"><em>Rysunek 2: Diagram Architektury Systemu aplikacji ŁapGo.</em></p>',23)])])}const k=i(l,[["render",s]]);export{p as __pageData,k as default};
